gqN(){return"\u0627\u0644\u0645\u0642\u0637\u0639 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gqP(){return"\u0641\u0646\u0627\u0646\u0648\u0646 \u0641\u0631\u064a\u062f\u0648\u0646"},
