guh(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gui(){return"\u064a\u062a\u064a\u062d \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0625\u0636\u0627\u0641\u0629 \u0623\u063a\u0646\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u062a\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629\u064b \u0641\u064a \u062d\u0633\u0627\u0628\u0643 \u0639\u0644\u0649 Last.fm."},
gun(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0640 Last.fm"},
gA3(){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0645\u0646 32 \u062d\u0631\u0641\u064b\u0627."},
gA1(){return"\u062a\u0641\u0648\u064a\u0636 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gA_(){return"\u0641\u0648\u0651\u0636 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u064a \u0635\u0641\u062d\u0629 Last.fm \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629 \u0641\u064a \u0627\u0644\u0645\u062a\u0635\u0641\u062d\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0647\u0646\u0627 \u0644\u0644\u062a\u0623\u0643\u064a\u062f."},
gA0(){return"\u0644\u0642\u062f \u0642\u0645\u062a \u0628\u0627\u0644\u062a\u0641\u0648\u064a\u0636"},
gA4(){return"\u062a\u0645 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0628\u0646\u062c\u0627\u062d!"},
gA2(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629. \u062a\u0623\u0643\u0651\u062f \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0648\u0645\u0646 \u0623\u0646\u0643 \u0645\u0646\u062d\u062a LastStats \u0627\u0644\u0625\u0630\u0646 \u0639\u0644\u0649 Last.fm\u060c \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627."},
